python -W ignore -c 'import csv
from pymatgen.core import Structure
from pymatgen.analysis.local_env import CrystalNN
from pymatgen.analysis.dimensionality import get_dimensionality_larsen
from pymatgen.analysis.graphs import StructureGraph
ids={"c005","c006","c007","c020","c024","c038","c039","c047","c048","c049","c053","c055","c060","c061","c062","c063","c064","c066","c069","c073","c074","c076","c077","c078","c079","c080","c081","c083","c084","c085","c086","c087","c088","c089","c090","c092"}
for r in csv.DictReader(open("nlo_pool.csv")):
 if r["candidate_id"] not in ids: continue
 s=Structure.from_str(r["poscar"],fmt="poscar")
 try: d=get_dimensionality_larsen(StructureGraph.with_local_env_strategy(s,CrystalNN()))
 except Exception as e: d="?"
 cn=[]
 nn=CrystalNN()
 for i,site in enumerate(s):
  try: cn.append(f"{site.specie.symbol}{len(nn.get_nn_info(s,i))}")
  except: cn.append(f"{site.specie.symbol}?")
 from collections import Counter
 print(r["candidate_id"],r["formula"],"dim",d,"CN",dict(Counter(cn)))'

python -c 'import csv
from pymatgen.core import Structure
ids={"c040","c041","c042","c043","c044","c045"}
for r in csv.DictReader(open("nlo_pool.csv")):
 if r["candidate_id"] not in ids: continue
 s=Structure.from_str(r["poscar"],fmt="poscar"); print("\n"+r["candidate_id"])
 for i,x in enumerate(s):
  if x.species_string=="B":
   ns=sorted((n.nn_distance,n.species_string,np.array(n.coords)-x.coords) for n in s.get_neighbors(x,2.2))
