python -c 'import csv,numpy as np
from pymatgen.core import Structure
ids={f"c{i:03}" for i in range(40,46)}
for r in csv.DictReader(open("nlo_pool.csv")):
 if r["candidate_id"] not in ids:continue
 s=Structure.from_str(r["poscar"],fmt="poscar"); T=np.zeros((3,3)); n=0
 for i,x in enumerate(s):
  if x.species_string!="B":continue
  for z in s.get_neighbors(x,2.2):
   v=np.array(z.coords)-x.coords; u=v/np.linalg.norm(v); T+=np.outer(u,u)/z.nn_distance**2;n+=1
 T/=s.volume; ev=np.linalg.eigvalsh(T)
 print(r["candidate_id"],"rho",round(s.density,3),"eig",np.round(ev,5),"spread",round(ev[-1]-ev[0],5),"frac",round((ev[-1]-ev[0])/ev.mean(),3))'

python -c 'import csv
from pymatgen.core import Structure
from pymatgen.analysis.structure_matcher import StructureMatcher
rows={r["candidate_id"]:Structure.from_str(r["poscar"],fmt="poscar") for r in csv.DictReader(open("nlo_pool.csv"))}
for group in [[f"c{i:03}" for i in range(1,5)],[f"c{i:03}" for i in range(8,14)],[f"c{i:03}" for i in range(40,46)],["c061","c089"]]:
 print("group",group)
 sm=StructureMatcher(ltol=.2,stol=.3,angle_tol=5,primitive_cell=True,scale=True,attempt_supercell=True,comparator=None)
 for i,a in enumerate(group):
  print(a,[b for b in group[i+1:] if sm.fit_anonymous(rows[a],rows[b])])'

